34	public class CompatibleTypeUtils {
35	
36	    private static final String DATE_FORMAT = "yyyy-MM-dd HH:mm:ss";
37	
38	    /**
39	     * the text to parse such as "2007-12-03T10:15:30"
40	     */
41	    private static final int ISO_LOCAL_DATE_TIME_MIN_LEN = 19;
42	
43	    private CompatibleTypeUtils() {}
44	
45	    /**
46	     * Compatible type convert. Null value is allowed to pass in. If no conversion is needed, then the original value
47	     * will be returned.
48	     * <p>
49	     * Supported compatible type conversions include (primary types and corresponding wrappers are not listed):
50	     * <ul>
51	     * <li> String -> char, enum, Date
52	     * <li> byte, short, int, long -> byte, short, int, long
53	     * <li> float, double -> float, double
54	     * </ul>
55	     */
56	    @SuppressWarnings({"unchecked", "rawtypes"})
57	    public static Object compatibleTypeConvert(Object value, Class<?> type) {
58	        if (value == null || type == null || type.isAssignableFrom(value.getClass())) {
59	            return value;
60	        }
61	
62	        if (value instanceof String) {
63	            String string = (String) value;
64	            if (char.class.equals(type) || Character.class.equals(type)) {
65	                if (string.length() != 1) {
66	                    throw new IllegalArgumentException(String.format(
67	                            "CAN NOT convert String(%s) to char!"
68	                                    + " when convert String to char, the String MUST only 1 char.",
69	                            string));
70	                }
71	                return string.charAt(0);
72	            }
73	            if (type.isEnum()) {
74	                return Enum.valueOf((Class<Enum>) type, string);
75	            }
76	            if (type == BigInteger.class) {
77	                return new BigInteger(string);
78	            }
79	            if (type == BigDecimal.class) {
80	                return new BigDecimal(string);
81	            }
82	            if (type == Short.class || type == short.class) {
83	                return new Short(string);
84	            }
85	            if (type == Integer.class || type == int.class) {
86	                return new Integer(string);
87	            }
88	            if (type == Long.class || type == long.class) {
89	                return new Long(string);
90	            }
91	            if (type == Double.class || type == double.class) {
92	                return new Double(string);
93	            }
94	            if (type == Float.class || type == float.class) {
95	                return new Float(string);
96	            }
97	            if (type == Byte.class || type == byte.class) {
98	                return new Byte(string);
99	            }
100	            if (type == Boolean.class || type == boolean.class) {
101	                return Boolean.valueOf(string);
102	            }
103	            if (type == Date.class
104	                    || type == java.sql.Date.class
105	                    || type == java.sql.Timestamp.class
106	                    || type == java.sql.Time.class) {
107	                try {
108	                    Date date = new SimpleDateFormat(DATE_FORMAT).parse(string);
109	                    if (type == java.sql.Date.class) {
110	                        return new java.sql.Date(date.getTime());
111	                    }
112	                    if (type == java.sql.Timestamp.class) {
113	                        return new java.sql.Timestamp(date.getTime());
114	                    }
115	                    if (type == java.sql.Time.class) {
116	                        return new java.sql.Time(date.getTime());
117	                    }
118	                    return date;
119	                } catch (ParseException e) {
120	                    throw new IllegalStateException(
121	                            "Failed to parse date " + value + " by format " + DATE_FORMAT + ", cause: "
122	                                    + e.getMessage(),
123	                            e);
124	                }
125	            }
126	            if (type == java.time.LocalDateTime.class) {
127	                if (StringUtils.isEmpty(string)) {
128	                    return null;
129	                }
130	                return LocalDateTime.parse(string);
131	            }
132	            if (type == java.time.LocalDate.class) {
133	                if (StringUtils.isEmpty(string)) {
134	                    return null;
135	                }
136	                return LocalDate.parse(string);
137	            }
138	            if (type == java.time.LocalTime.class) {
139	                if (StringUtils.isEmpty(string)) {
140	                    return null;
141	                }
142	
143	                if (string.length() >= ISO_LOCAL_DATE_TIME_MIN_LEN) {
144	                    return LocalDateTime.parse(string).toLocalTime();
145	                } else {
146	                    return LocalTime.parse(string);
147	                }
148	            }
149	            if (type == Class.class) {
150	                try {
151	                    return ReflectUtils.name2class(string);
152	                } catch (ClassNotFoundException e) {
153	                    throw new RuntimeException(e.getMessage(), e);
154	                }
155	            }
156	            if (char[].class.equals(type)) {
157	                // Process string to char array for generic invoke
158	                // See
159	                // - https://github.com/apache/dubbo/issues/2003
160	                int len = string.length();
161	                char[] chars = new char[len];
162	                string.getChars(0, len, chars, 0);
163	                return chars;
164	            }
165	        }
166	        if (value instanceof Number) {
167	            Number number = (Number) value;
168	            if (type == byte.class || type == Byte.class) {
169	                return number.byteValue();
170	            }
171	            if (type == short.class || type == Short.class) {
172	                return number.shortValue();
173	            }
174	            if (type == int.class || type == Integer.class) {
175	                return number.intValue();
176	            }
177	            if (type == long.class || type == Long.class) {
178	                return number.longValue();
179	            }
180	            if (type == float.class || type == Float.class) {
181	                return number.floatValue();
182	            }
183	            if (type == double.class || type == Double.class) {
184	                return number.doubleValue();
185	            }
186	            if (type == BigInteger.class) {
187	                return number instanceof BigDecimal
188	                        ? ((BigDecimal) number).toBigInteger()
189	                        : BigInteger.valueOf(number.longValue());
190	            }
191	            if (type == BigDecimal.class) {
192	                return new BigDecimal(number.toString());
193	            }
194	            if (type == Date.class) {
195	                return new Date(number.longValue());
196	            }
197	            if (type == boolean.class || type == Boolean.class) {
198	                return 0 != number.intValue();
199	            }
200	        }
201	        if (value instanceof Collection) {
202	            Collection collection = (Collection) value;
203	            if (type.isArray()) {
204	                int length = collection.size();
205	                Object array = Array.newInstance(type.getComponentType(), length);
206	                int i = 0;
207	                for (Object item : collection) {
208	                    Array.set(array, i++, item);
209	                }
210	                return array;
211	            }
212	            if (!type.isInterface()) {
213	                try {
214	                    Collection result =
215	                            (Collection) type.getDeclaredConstructor().newInstance();
216	                    result.addAll(collection);
217	                    return result;
218	                } catch (Throwable ignored) {
219	                }
220	            }
221	            if (type == List.class) {
222	                return new ArrayList<Object>(collection);
223	            }
224	            if (type == Set.class) {
225	                return new HashSet<Object>(collection);
226	            }
227	        }
228	        if (value.getClass().isArray() && Collection.class.isAssignableFrom(type)) {
229	            int length = Array.getLength(value);
230	            Collection collection;
231	            if (!type.isInterface()) {
232	                try {
233	                    collection = (Collection) type.getDeclaredConstructor().newInstance();
234	                } catch (Exception e) {
235	                    collection = new ArrayList<Object>(length);
236	                }
237	            } else if (type == Set.class) {
238	                collection = new HashSet<Object>(Math.max((int) (length / .75f) + 1, 16));
239	            } else {
240	                collection = new ArrayList<Object>(length);
241	            }
242	            for (int i = 0; i < length; i++) {
243	                collection.add(Array.get(value, i));
244	            }
245	            return collection;
246	        }
247	        return value;
248	    }
249	}
