388	    public static Set<Class<?>> getAllSuperClasses(Class<?> type, Predicate<Class<?>>... classFilters) {
389	
390	        Set<Class<?>> allSuperClasses = new LinkedHashSet<>();
391	
392	        Class<?> superClass = type.getSuperclass();
393	        while (superClass != null) {
394	            // add current super class
395	            allSuperClasses.add(superClass);
396	            superClass = superClass.getSuperclass();
397	        }
398	
399	        return unmodifiableSet(filterAll(allSuperClasses, classFilters));
400	    }
