72	public class ConditionStateRouter<T> extends AbstractStateRouter<T> {
73	    public static final String NAME = "condition";
74	
75	    private static final ErrorTypeAwareLogger logger = LoggerFactory.getErrorTypeAwareLogger(AbstractStateRouter.class);
76	    protected static final Pattern ROUTE_PATTERN = Pattern.compile("([&!=,]*)\\s*([^&!=,\\s]+)");
77	    protected Map<String, ConditionMatcher> whenCondition;
