106	    public void init(String rule) {
107	        try {
108	            if (rule == null || rule.trim().length() == 0) {
109	                throw new IllegalArgumentException("Illegal route rule!");
110	            }
111	            rule = rule.replace("consumer.", "").replace("provider.", "");
112	            int i = rule.indexOf("=>");
113	            String whenRule = i < 0 ? null : rule.substring(0, i).trim();
114	            String thenRule = i < 0 ? rule.trim() : rule.substring(i + 2).trim();
115	            Map<String, ConditionMatcher> when =
116	                    StringUtils.isBlank(whenRule) || "true".equals(whenRule) ? new HashMap<>() : parseRule(whenRule);
117	            Map<String, ConditionMatcher> then =
118	                    StringUtils.isBlank(thenRule) || "false".equals(thenRule) ? null : parseRule(thenRule);
119	            // NOTE: It should be determined on the business level whether the `When condition` can be empty or not.
120	            this.whenCondition = when;
121	            this.thenCondition = then;
122	        } catch (ParseException e) {
123	            throw new IllegalStateException(e.getMessage(), e);
124	        }
