127	    private Map<String, ConditionMatcher> parseRule(String rule) throws ParseException {
128	        Map<String, ConditionMatcher> condition = new HashMap<>();
129	        if (StringUtils.isBlank(rule)) {
130	            return condition;
131	        }
132	        // Key-Value pair, stores both match and mismatch conditions
133	        ConditionMatcher matcherPair = null;
134	        // Multiple values
135	        Set<String> values = null;
136	        final Matcher matcher = ROUTE_PATTERN.matcher(rule);
137	        while (matcher.find()) { // Try to match one by one
138	            String separator = matcher.group(1);
139	            String content = matcher.group(2);
140	            // Start part of the condition expression.
141	            if (StringUtils.isEmpty(separator)) {
142	                matcherPair = this.getMatcher(content);
143	                condition.put(content, matcherPair);
144	            }
145	            // The KV part of the condition expression
146	            else if ("&".equals(separator)) {
147	                if (condition.get(content) == null) {
148	                    matcherPair = this.getMatcher(content);
149	                    condition.put(content, matcherPair);
150	                } else {
151	                    matcherPair = condition.get(content);
152	                }
153	            }
154	            // The Value in the KV part.
155	            else if ("=".equals(separator)) {
156	                if (matcherPair == null) {
157	                    throw new ParseException(
158	                            "Illegal route rule \""
159	                                    + rule + "\", The error char '" + separator
160	                                    + "' at index " + matcher.start() + " before \""
161	                                    + content + "\".",
162	                            matcher.start());
163	                }
164	
165	                values = matcherPair.getMatches();
166	                values.add(content);
167	            }
168	            // The Value in the KV part.
169	            else if ("!=".equals(separator)) {
170	                if (matcherPair == null) {
171	                    throw new ParseException(
172	                            "Illegal route rule \""
173	                                    + rule + "\", The error char '" + separator
174	                                    + "' at index " + matcher.start() + " before \""
175	                                    + content + "\".",
176	                            matcher.start());
177	                }
178	
179	                values = matcherPair.getMismatches();
180	                values.add(content);
181	            }
182	            // The Value in the KV part, if Value have more than one items.
183	            else if (",".equals(separator)) { // Should be separated by ','
184	                if (values == null || values.isEmpty()) {
185	                    throw new ParseException(
186	                            "Illegal route rule \""
187	                                    + rule + "\", The error char '" + separator
188	                                    + "' at index " + matcher.start() + " before \""
189	                                    + content + "\".",
190	                            matcher.start());
191	                }
192	                values.add(content);
193	            } else {
194	                throw new ParseException(
195	                        "Illegal route rule \"" + rule
196	                                + "\", The error char '" + separator + "' at index "
197	                                + matcher.start() + " before \"" + content + "\".",
198	                        matcher.start());
199	            }
200	        }
201	        return condition;
202	    }
