204	    @Override
205	    protected BitList<Invoker<T>> doRoute(
206	            BitList<Invoker<T>> invokers,
207	            URL url,
208	            Invocation invocation,
209	            boolean needToPrintMessage,
210	            Holder<RouterSnapshotNode<T>> nodeHolder,
211	            Holder<String> messageHolder)
212	            throws RpcException {
213	        if (!enabled) {
214	            if (needToPrintMessage) {
215	                messageHolder.set("Directly return. Reason: ConditionRouter disabled.");
216	            }
217	            return invokers;
218	        }
219	
220	        if (CollectionUtils.isEmpty(invokers)) {
221	            if (needToPrintMessage) {
222	                messageHolder.set("Directly return. Reason: Invokers from previous router is empty.");
223	            }
224	            return invokers;
225	        }
226	        try {
227	            if (!matchWhen(url, invocation)) {
228	                if (needToPrintMessage) {
229	                    messageHolder.set("Directly return. Reason: WhenCondition not match.");
230	                }
231	                return invokers;
232	            }
233	            if (thenCondition == null) {
234	                logger.warn(
235	                        CLUSTER_CONDITIONAL_ROUTE_LIST_EMPTY,
236	                        "condition state router thenCondition is empty",
237	                        "",
238	                        "The current consumer in the service blocklist. consumer: " + NetUtils.getLocalHost()
239	                                + ", service: " + url.getServiceKey());
240	                if (needToPrintMessage) {
241	                    messageHolder.set("Empty return. Reason: ThenCondition is empty.");
242	                }
243	                return BitList.emptyList();
244	            }
245	            BitList<Invoker<T>> result = invokers.clone();
246	            result.removeIf(invoker -> !matchThen(invoker.getUrl(), url));
247	
248	            if (!result.isEmpty()) {
249	                if (needToPrintMessage) {
250	                    messageHolder.set("Match return.");
251	                }
252	                return result;
253	            } else if (this.isForce()) {
254	                logger.warn(
255	                        CLUSTER_CONDITIONAL_ROUTE_LIST_EMPTY,
256	                        "execute condition state router result list is empty. and force=true",
257	                        "",
258	                        "The route result is empty and force execute. consumer: " + NetUtils.getLocalHost()
259	                                + ", service: " + url.getServiceKey() + ", router: "
260	                                + url.getParameterAndDecoded(RULE_KEY));
261	                if (needToPrintMessage) {
262	                    messageHolder.set("Empty return. Reason: Empty result from condition and condition is force.");
263	                }
264	                return result;
265	            }
266	        } catch (Throwable t) {
267	            logger.error(
268	                    CLUSTER_FAILED_EXEC_CONDITION_ROUTER,
269	                    "execute condition state router exception",
270	                    "",
271	                    "Failed to execute condition router rule: " + getUrl() + ", invokers: " + invokers + ", cause: "
272	                            + t.getMessage(),
273	                    t);
274	        }
275	        if (needToPrintMessage) {
276	            messageHolder.set("Directly return. Reason: Error occurred ( or result is empty ).");
277	        }
278	        return invokers;
279	    }
