281	    @Override
282	    public boolean isRuntime() {
283	        // We always return true for previously defined Router, that is, old Router doesn't support cache anymore.
284	        //        return true;
285	        return this.getUrl().getParameter(RUNTIME_KEY, false);
286	    }
