288	    private ConditionMatcher getMatcher(String key) {
289	        for (ConditionMatcherFactory factory : matcherFactories) {
290	            if (factory.shouldMatch(key)) {
291	                return factory.createMatcher(key, moduleModel);
292	            }
293	        }
294	        return moduleModel
295	                .getExtensionLoader(ConditionMatcherFactory.class)
296	                .getExtension("param")
297	                .createMatcher(key, moduleModel);
298	    }
299	
300	    boolean matchWhen(URL url, Invocation invocation) {
301	        if (CollectionUtils.isEmptyMap(whenCondition)) {
302	            return true;
303	        }
304	
305	        return doMatch(url, null, invocation, whenCondition, true);
306	    }
307	
308	    private boolean matchThen(URL url, URL param) {
309	        if (CollectionUtils.isEmptyMap(thenCondition)) {
310	            return false;
311	        }
312	
313	        return doMatch(url, param, null, thenCondition, false);
314	    }
315	
316	    private boolean doMatch(
317	            URL url,
318	            URL param,
319	            Invocation invocation,
320	            Map<String, ConditionMatcher> conditions,
321	            boolean isWhenCondition) {
322	        Map<String, String> sample = url.toOriginalMap();
323	        for (Map.Entry<String, ConditionMatcher> entry : conditions.entrySet()) {
324	            ConditionMatcher matchPair = entry.getValue();
325	            if (!matchPair.isMatch(sample, param, invocation, isWhenCondition)) {
326	                return false;
327	            }
328	        }
329	        return true;
330	    }
